import pytest
import torch

import flag_gems

from .base import Benchmark


class ToDenseBackwardBenchmark(Benchmark):
    def get_input_iter(self, cur_dtype):
        # The strided path is a dtype conversion whose cost scales with numel;
        # float32 -> float16 covers the common backward cast.
        for shape in [(1024,), (65536,), (1048576,), (16777216,)]:
            grad = torch.randn(shape, device=self.device, dtype=torch.float32)
            input = torch.randn(shape, device=self.device, dtype=cur_dtype)
            yield grad, input
        grad = torch.randn((1024, 1024), device=self.device, dtype=torch.float32)
        input = torch.randn((1024, 1024), device=self.device, dtype=cur_dtype)
        yield grad, input.t()


